import "C"
import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"unsafe"
)

const (
	maxUploadSize = 10 << 20 // 10MB
	uploadDir     = "./uploads"
)

type ChatRoom struct {
	mu       sync.RWMutex
	clients  map[string]chan []byte
	uploads  map[string]*MediaMeta
}

type MediaMeta struct {
	ID       string
	Filename string
	Size     int64
	MIME     string
	Owner    string
}

var room = &ChatRoom{
	clients: make(map[string]chan []byte),
	uploads: make(map[string]*MediaMeta),
}

func generateID() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func sanitizeFilename(name string) string {
	name = filepath.Base(name)
	name = strings.ReplaceAll(name, "..", "")
	name = strings.Map(func(r rune) rune {
		if r == '/' || r == '\\' || r == '\x00' {
			return -1
		}
		return r
	}, name)
	return name
}

func validateMIME(data []byte) string {
	mime := http.DetectContentType(data)
	allowed := []string{"image/jpeg", "image/png", "image/gif", "video/mp4", "audio/mpeg"}
	for _, a := range allowed {
		if strings.HasPrefix(mime, a) {
			return mime
		}
	}
	return ""
}

func processMediaUpload(data []byte, quality int) ([]byte, bool) {
	cData := C.CBytes(data)
	defer C.free(cData)

	buf := C.process_media((*C.uchar)(cData), C.size_t(len(data)), C.int(quality))
	if buf == nil {
		return nil, false
	}
	defer C.free_media_buffer(buf)

	result := C.GoBytes(unsafe.Pointer(buf.data), C.int(buf.len))
	return result, buf.processed == 1
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	user := r.Header.Get("X-User-ID")
	if user == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxUploadSize)
	if err := r.ParseMultipartForm(maxUploadSize); err != nil {
		http.Error(w, "File too large", http.StatusRequestEntityTooLarge)
		return
	}

	file, header, err := r.FormFile("media")
	if err != nil {
		http.Error(w, "Invalid file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	data, err := io.ReadAll(file)
	if err != nil {
		http.Error(w, "Read error", http.StatusInternalServerError)
		return
	}

	mime := validateMIME(data)
	if mime == "" {
		http.Error(w, "Unsupported media type", http.StatusUnsupportedMediaType)
		return
	}

	quality := 80
	if q := r.FormValue("quality"); q != "" {
		fmt.Sscanf(q, "%d", &quality)
	}

	processed, ok := processMediaUpload(data, quality)
	if !ok {
		processed = data
	}

	id := generateID()
	safeName := sanitizeFilename(header.Filename)
	outPath := filepath.Join(uploadDir, id+"_"+safeName)

	if err := os.WriteFile(outPath, processed, 0644); err != nil {
		http.Error(w, "Storage error", http.StatusInternalServerError)
		return
	}

	meta := &MediaMeta{
		ID:       id,
		Filename: safeName,
		Size:     int64(len(processed)),
		MIME:     mime,
		Owner:    user,
	}

	room.mu.Lock()
	room.uploads[id] = meta
	room.mu.Unlock()

	room.mu.RLock()
	msg := []byte(fmt.Sprintf(`{"type":"media","id":"%s","from":"%s","mime":"%s"}`, id, user, mime))
	for _, ch := range room.clients {
		select {
		case ch <- msg:
		default:
		}
	}
	room.mu.RUnlock()

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"id":"%s","status":"ok"}`, id)
}

func main() {
	C.init_jvm()
	os.MkdirAll(uploadDir, 0755)
	http.HandleFunc("/upload", uploadHandler)
	http.HandleFunc("/media/", func(w http.ResponseWriter, r *http.Request) {
		id := strings.TrimPrefix(r.URL.Path, "/media/")
		room.mu.RLock()
		meta, ok := room.uploads[id]
		room.mu.RUnlock()
		if !ok {
			http.Error(w, "Not found", http.StatusNotFound)
			return
		}
		w.Header().Set("Content-Type", meta.MIME)
		http.ServeFile(w, r, filepath.Join(uploadDir, id+"_"+meta.Filename))
	})
	fmt.Println("Chat server starting on :8080")
	http.ListenAndServe(":8080", nil)
}
